/// Spacing scale (logical pixels). Eight steps, no more.
abstract final class MiraSpace {
  /// Icon-to-label gap.
  static const double space1 = 4;
  /// Inside pills and chips; between stacked label and field.
  static const double space2 = 8;
  /// Between controls in a row; dense table cell padding.
  static const double space3 = 12;
  /// Card and call-panel padding.
  static const double space4 = 16;
  /// Between cards; dialog padding.
  static const double space6 = 24;
  /// Section gaps; wallboard tile padding.
  static const double space8 = 32;
  /// Page margins on wallboards and marketing.
  static const double space12 = 48;
  /// Hero and slide padding.
  static const double space16 = 64;
}

/// Corner radii. `pill` = fully rounded.
abstract final class MiraRadius {
  /// Pills' inner chips, inputs, table tags.
  static const double sm = 6;
  /// Buttons, inputs, small cards.
  static const double md = 10;
  /// Cards, call panel, KPI tiles, dialogs.
  static const double lg = 16;
  /// Brand blocks, app icon, mobile sheets — echoes the logo's soft blocky corners.
  static const double xl = 24;
  /// Status pills; round call buttons and dial keys.
  static const double pill = 999;
}

/// Component sizes (logical pixels).
abstract final class MiraSize {
  /// Compact buttons and inputs in tables.
  static const double controlSm = 32;
  /// Default button and input height (desktop).
  static const double controlMd = 40;
  /// Mobile buttons and inputs; primary actions on touch screens.
  static const double controlLg = 48;
  /// Minimum touch target on any touch surface (Apple HIG).
  static const double touchMin = 44;
  /// Round Answer / Hang-up buttons.
  static const double callButton = 64;
  /// Dial pad key on mobile and desktop softphone.
  static const double dialKey = 72;
  /// Mira Desk navigation rail, expanded.
  static const double sidebar = 240;
  /// Docked call panel width in Mira Desk.
  static const double callPanel = 360;
}

/// Motion durations.
abstract final class MiraDuration {
  /// Hover, press, toggle.
  static const Duration fast = Duration(milliseconds: 120);
  /// Panels, pills changing state.
  static const Duration base = Duration(milliseconds: 200);
  /// Call panel slide-in, page transitions. Never longer.
  static const Duration slow = Duration(milliseconds: 320);
}

/// Motion curves.
abstract final class MiraEasing {
  /// Default easing for all transitions.
  static const Cubic standard = Cubic(0.2, 0, 0, 1);
  /// Elements leaving (dismissed toast, closed panel).
  static const Cubic exit = Cubic(0.4, 0, 1, 1);
}

/// Font families. Fonts are bundled with the app (OFL-licensed IBM Plex and Archivo).
abstract final class MiraFonts {
  static const String display = 'Archivo';
  static const String sans = 'IBM Plex Sans';
  static const String arabic = 'IBM Plex Sans Arabic';
  static const String mono = 'IBM Plex Mono';
}

