/// Brand-only shadows (marketing, login screen) — never in dense product UI.
abstract final class MiraBrandShadows {
  /// BRAND ONLY: the logo's extruded block, on red tiles in marketing, slides and the login screen. Never in dense product UI.
  static const List<BoxShadow> extrude = [BoxShadow(offset: Offset(6, 6), blurRadius: 0, spreadRadius: 0, color: Color(0xFF9E0407))];
}
